#![allow(unused)]
use verus::prelude::*;

verus! {

    /// Given a nonempty `arr` of `i8` values, return the
    /// (leftmost) index of a maximal element.
    ///
    /// requires:
    ///   `arr.len() > 0`
    ///
    /// ensures:
    ///   `result < arr.len()`
    ///   forall `i < arr.len()`: `arr[i] <= arr[result]`
    ///   forall `i < result`:    `arr[i] <  arr[result]`
    fn argmax(arr: &Vec<i8>) -> usize
        requires
            arr.len() > 0,
        ensures
            result < arr.len(),
        ensures
            forall |i: usize| i < arr.len() ==> arr[i] <= arr[result],
        ensures
            forall |i: usize| i < result    ==> arr[i] <  arr[result],
    {
        // best is always the index of the max in arr[0..i),
        // and i traverses from 1 up to arr.len().
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < arr.len()
            invariant
                // bounds on i
                1 <= i && i <= arr.len(),
            invariant
                // best is always a valid index in [0, i)
                best < i,
            invariant
                // arr[best] is the maximum over [0, i)
                forall |k: usize| k < i ==> arr[k] <= arr[best],
            invariant
                // leftmostness: any index < best is strictly smaller
                forall |k: usize| k < best ==> arr[k] < arr[best],
            decreases
                // the distance to the end strictly decreases
                arr.len() - i,
        {
            if arr[i] > arr[best] {
                best = i;
            }
            i += 1;
        }
        best
    }

}